SELECT ((COUNT(?p1) * 100.0) / ?total AS ?percentage)
WHERE {
  {
    SELECT (COUNT(?p) AS ?total)
    WHERE {
      ?p a <http://bird-bird_thrombosis_prediction-ontology-20260805-013315/ontology/vkg-bird_thrombosis_prediction/Patient> ;
         <http://bird-bird_thrombosis_prediction-ontology-20260805-013315/ontology/vkg-bird_thrombosis_prediction/Patient/sex> ?sex .
      FILTER(?sex = "F")
    }
  }
  ?p1 a <http://bird-bird_thrombosis_prediction-ontology-20260805-013315/ontology/vkg-bird_thrombosis_prediction/Patient> ;
      <http://bird-bird_thrombosis_prediction-ontology-20260805-013315/ontology/vkg-bird_thrombosis_prediction/Patient/sex> ?sex1 ;
      <http://bird-bird_thrombosis_prediction-ontology-20260805-013315/ontology/vkg-bird_thrombosis_prediction/Patient/birthday> ?b .
  FILTER(?sex1 = "F")
  BIND(xsd:integer(SUBSTR(STR(?b), 1, 4)) AS ?year)
  FILTER(?year > 1930)
}
GROUP BY ?total

